    Lemma sc_cl : forall (k : nat) (j : Z) x1 x5 x10 x11 x12 x13 x14 x15 x16 x17 x21 x22 x23 x24 x25 x26 x27,
      Z.to_nat (Z.of_nat (cmpi e t) - j) = k -> 0 <= j <= Z.of_nat (cmpi e t) ->
